exercise.referenceSolution:
#include <stdio.h>

int main(void) {
    FILE *out = fopen("input.bin", "wb");
    if (out == NULL) {
        return 1;
    }
    unsigned char chunk[256];
    size_t got;
    while ((got = fread(chunk, 1, sizeof chunk, stdin)) > 0) {
        fwrite(chunk, 1, got, out);
    }
    fclose(out);

    FILE *in = fopen("input.bin", "rb");
    if (in == NULL) {
        return 1;
    }
    unsigned char block[16];
    unsigned long offset = 0;
    size_t n;
    while ((n = fread(block, 1, sizeof block, in)) > 0) {
        printf("%08lx  ", offset);
        for (size_t i = 0; i < 16; i++) {
            if (i < n) {
                printf("%02x ", block[i]);
            } else {
                printf("   ");
            }
            if (i == 7) {
                putchar(' ');
            }
        }
        printf(" |");
        for (size_t i = 0; i < n; i++) {
            putchar(block[i] >= 32 && block[i] <= 126 ? block[i] : '.');
        }
        printf("|\n");
        offset += n;
    }
    if (offset > 0) {
        printf("%08lx\n", offset);
    }
    fclose(in);
    return 0;
}

