#include <stdint.h>
#include <stdio.h>
#include <string.h>

static uint32_t u16(const unsigned char *p) {
    return (uint32_t)p[0] | (uint32_t)p[1] << 8;
}

static uint32_t u32(const unsigned char *p) {
    return (uint32_t)p[0] | (uint32_t)p[1] << 8 | (uint32_t)p[2] << 16 | (uint32_t)p[3] << 24;
}

static long long s32(const unsigned char *p) {
    uint32_t u = u32(p);
    return u >= 0x80000000u ? (long long)u - 4294967296LL : (long long)u;
}

int main(void) {
    FILE *f = tmpfile();
    if (f == NULL) {
        return 1;
    }
    unsigned v;
    while (scanf("%x", &v) == 1 && v <= 0xFF) {
        unsigned char b = (unsigned char)v;
        fwrite(&b, 1, 1, f);
    }
    rewind(f);
    unsigned char h[54];
    size_t got = fread(h, 1, sizeof h, f);
    fclose(f);
    if (got < 2 || h[0] != 'B' || h[1] != 'M') {
        printf("ошибка: не BMP\n");
        return 0;
    }
    if (got < 54) {
        printf("ошибка: файл обрезан\n");
        return 0;
    }
    if (u32(h + 14) != 40) {
        printf("ошибка: неподдерживаемый заголовок\n");
        return 0;
    }
    long long width = s32(h + 18), height = s32(h + 22);
    if (u16(h + 26) != 1 || width <= 0 || height == 0) {
        printf("ошибка: повреждён заголовок\n");
        return 0;
    }
    printf("BMP %lldx%lld, %u бит, сжатие %u, данные с %u, размер файла %u%s\n", width,
           height < 0 ? -height : height, (unsigned)u16(h + 28), (unsigned)u32(h + 30),
           (unsigned)u32(h + 10), (unsigned)u32(h + 2), height < 0 ? ", сверху вниз" : "");
    return 0;
}

additionalExercises.description:
Сохраните таблицу рекордов в собственном двоичном формате и прочитайте её обратно. Каждая строка ввода — `имя очки`. Формат файла `scores.bin`:
- сигнатура — 4 байта `SCR1`;
- число записей — 2 байта, little-endian;
- для каждой записи: длина имени (1 байт), байты имени без завершающего нуля, очки — 4 байта, little-endian, в дополнительном коде.

Запишите файл, затем напечатайте `файл: N байтов` и все его байты одной строкой — по две строчные шестнадцатеричные цифры без пробелов. После этого откройте файл заново, разберите его (проверив сигнатуру и длины) и напечатайте записи как `имя: очки`. Если записей нет, после строки с байтами ничего не печатайте.

