additionalExercises.referenceSolution:
#include <stdint.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    char name[21];
    long long score;
} Record;

static void put_u32(FILE *f, uint32_t v) {
    for (int i = 0; i < 4; i++) {
        fputc((int)((v >> (8 * i)) & 0xFFu), f);
    }
}

static int get_u32(FILE *f, uint32_t *v) {
    unsigned char b[4];
    if (fread(b, 1, 4, f) != 4) {
        return 0;
    }
    *v = (uint32_t)b[0] | (uint32_t)b[1] << 8 | (uint32_t)b[2] << 16 | (uint32_t)b[3] << 24;
    return 1;
}

int main(void) {
    Record records[50];
    int count = 0;
    while (count < 50 && scanf("%20s %lld", records[count].name, &records[count].score) == 2) {
        count++;
    }
    FILE *f = fopen("scores.bin", "wb");
    if (f == NULL) {
        return 1;
    }
    fwrite("SCR1", 1, 4, f);
    fputc(count & 0xFF, f);
    fputc((count >> 8) & 0xFF, f);
    for (int i = 0; i < count; i++) {
        size_t len = strlen(records[i].name);
        fputc((int)len, f);
        fwrite(records[i].name, 1, len, f);
        put_u32(f, (uint32_t)records[i].score);
    }
    fclose(f);

    f = fopen("scores.bin", "rb");
    if (f == NULL) {
        return 1;
    }
    int c;
    long size = 0;
    char hex[4096] = "";
    const char *digits = "0123456789abcdef";
    while ((c = fgetc(f)) != EOF && size < 2000) {
        hex[2 * size] = digits[c >> 4];
        hex[2 * size + 1] = digits[c & 15];
        hex[2 * size + 2] = '\0';
        size++;
    }
    printf("файл: %ld байтов\n%s\n", size, hex);

    rewind(f);
    unsigned char head[6];
    if (fread(head, 1, 6, f) != 6 || memcmp(head, "SCR1", 4) != 0) {
        printf("ошибка формата\n");
        fclose(f);
        return 0;
    }
    unsigned stored = head[4] | (unsigned)head[5] << 8;
    for (unsigned i = 0; i < stored; i++) {
        int len = fgetc(f);
        char name[21];
        uint32_t u;
        if (len == EOF || len < 1 || len > 20 || fread(name, 1, (size_t)len, f) != (size_t)len ||
            !get_u32(f, &u)) {
            printf("ошибка формата\n");
            break;
        }
        name[len] = '\0';
        long long score = u >= 0x80000000u ? (long long)u - 4294967296LL : (long long)u;
        printf("%s: %lld\n", name, score);
    }
    fclose(f);
    return 0;
}

additionalExercises.description:
Разберите формат **SENS/1** — файл измерений датчика — из настоящего двоичного потока `FILE *`. Спецификация:
- байт 0 — `83` (`S`), байт 1 — `78` (`N`): сигнатура;
- байт 2 — версия, допустима только 1;
- байт 3 — число записей `count` от 0 до 64;
- затем `count` записей — беззнаковых 16-битных измерений в порядке little-endian;
- файл содержит **ровно** `4 + 2 · count` байтов.

При неверной сигнатуре, версии или числе записей, при обрезанном файле или лишних байтах в конце напечатайте `ОШИБКА`; ошибка ввода-вывода — тоже `ОШИБКА`. При успехе напечатайте `count` и сумму измерений через пробел.

**Транспорт в тестах.** Стандартный ввод содержит число `n` (0…256) и `n` десятичных чисел — байтов файла (0…255). Программа-адаптер записывает их через `fwrite` во временный файл `tmpfile()` и возвращается к началу. Сам разборщик — функция, которая принимает `FILE *`, читает его через `fread`/`fgetc` и ничего не знает о стандартном вводе. Так через текстовое поле можно передать нулевые байты и заведомо испорченные файлы. В настоящем формате числа `n` нет.

