additionalExercises.referenceSolution:
#include <limits.h>
#include <stdio.h>

static_assert(CHAR_BIT == 8, "формат рассчитан на восьмибитные байты");

// Разбор формата SENS/1 из потока. Выходные параметры меняются только при успехе.
static int parse(FILE *file, unsigned *count, unsigned long *sum) {
    unsigned char header[4];
    if (fread(header, 1, 4, file) != 4) {
        return 0;
    }
    if (header[0] != 'S' || header[1] != 'N' || header[2] != 1 || header[3] > 64) {
        return 0;
    }
    unsigned long total = 0;
    for (unsigned i = 0; i < header[3]; i++) {
        unsigned char bytes[2];
        if (fread(bytes, 1, 2, file) != 2) {
            return 0;
        }
        total += (unsigned long)bytes[0] | (unsigned long)bytes[1] << 8;
    }
    if (fgetc(file) != EOF || ferror(file)) {
        return 0;
    }
    *count = header[3];
    *sum = total;
    return 1;
}

int main(void) {
    unsigned n;
    if (scanf("%u", &n) != 1 || n > 256) {
        return 1;
    }
    FILE *file = tmpfile();
    if (file == NULL) {
        return 1;
    }
    int valid = 1;
    for (unsigned i = 0; i < n && valid; i++) {
        unsigned x;
        if (scanf("%u", &x) != 1 || x > 255) {
            valid = 0;
            break;
        }
        unsigned char byte = (unsigned char)x;
        valid = fwrite(&byte, 1, 1, file) == 1;
    }
    unsigned count = 0;
    unsigned long sum = 0;
    valid = valid && fseek(file, 0, SEEK_SET) == 0 && parse(file, &count, &sum);
    if (fclose(file) != 0) {
        valid = 0;
    }
    if (valid) {
        printf("%u %lu\n", count, sum);
    } else {
        puts("ОШИБКА");
    }
    return 0;
}

